export function findAsset(series: string, doc: TemplateAsset["doc"], size: TemplateAsset["size"], format: TemplateAsset["format"], pages: number | null = 1) {
  return TEMPLATE_ASSETS.find((a) => a.series === series && a.doc === doc && a.size === size && a.format === format && (doc !== "resume" || a.pages === pages));
}
